#!/usr/bin/env python3"""Simple script to create a bed file of contig sizes from a fasta fileParameters------------fasta    Path to fasta file (can be gzipped)--contigs    Comma separated string of contigs to include    Names must match contigs in fasta    Omit to output all contigs in fasta file    (e.g. --fasta 1,2,3)"""### IMPORTS -------------------------------- ###import gzipfrom sys import argv### FUNCTIONS ------------------------------ ###def parse_args():        # Fasta path    fasta_path = argv[argv.index('--fasta') + 1]        # Contigs to use    desired_contigs = argv[argv.index('--contigs') + 1] if '--contigs' in argv else []        return fasta_path, desired_contigs### ---------------------------------------- ###def parse_fasta(path: str, contigs_to_keep: list[str]=[]) -> dict[str, int]:        # Load fasta    if path.endswith('.gz'):        contigs = gzip.open(path, 'r').read().decode().split('>')    else:            contigs = open(path, 'r').read().split('>')    # Parse fasta and get contig size    contig_sizes = {}    for c in contigs:        # Skip empty text chunk        if not len(c):            continue        # Extract contig name and sequence size        c = c.split('\n')        c_name = c[0].split(' ')[0]        c_seq = ''.join(c[1:])        if not len(contigs_to_keep) or c_name in contigs_to_keep:            contig_sizes[c_name] = len(c_seq)        return contig_sizes### MAIN ----------------------------------- ###if __name__ == '__main__':        # Parse CLI args    fasta_path, desired_contigs = parse_args()        # Extract contigs sizes    contig_sizes = parse_fasta(fasta_path, desired_contigs)        # Export to bed    with open('contigs.bed', 'w') as contigs_out:        contigs_out.write('\n'.join([f'{c_name}\t0\t{c_size}' for c_name,c_size in contig_sizes.items()]))    